//! Detached Param copies preserve real independent metadata.
use super::*;
fn fixture()->(Document,Forms,Page){fixture_with_markup("<html><body><param id=param name=seed value=seed type=seed valuetype=seed><input id=neighbor value=seed></body></html>")}
fn fixture_with_markup(markup:&str)->(Document,Forms,Page){let mut d=crate::html::parse(markup);d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://param-copy.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]fn param_detached_copy_native_clone_preserves_independent_all_field_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var x=document.getElementById('param');for(var pair of [['name','name'],['value','value'],['type','type'],['valueType','valuetype']])x[pair[0]]='A\udfffZ';var copy=x.cloneNode(false);
if(copy===x||!(copy instanceof HTMLParamElement)||copy.ownerDocument!==document||copy.parentNode!==null||copy.firstChild!==null)throw 'detached Param clone';
for(var pair of [['name','name'],['value','value'],['type','type'],['valueType','valuetype']]){var property=pair[0],attribute=pair[1],old=x.getAttributeNode(attribute),attr=copy.getAttributeNode(attribute);if(copy[property]!=='A\udfffZ'||attr===old||attr.value!==copy[property]||attr.ownerElement!==copy||attr.ownerDocument!==document)throw 'independent copied metadata';copy[property]='copy';if(x[property]!=='A\udfffZ'||old.value!=='A\udfffZ'||attr.value!=='copy')throw 'independent writes';}
"#);}
#[test]fn param_detached_copy_inert_import_preserves_source_owner_and_exact_fields(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','param');for(var property of ['name','value','type','valueType'])source[property]='A\ud800Z';var original=source.getAttributeNode('valuetype'),copy=document.importNode(source,false);if(!(copy instanceof HTMLParamElement)||copy.ownerDocument!==document||copy.parentNode!==null||source.ownerDocument!==owner||source.parentNode!==null||original.ownerDocument!==owner||copy.getAttributeNode('valuetype')===original)throw 'destination Param copy owner';for(var property of ['name','value','type','valueType']){if(copy[property]!=='A\ud800Z')throw 'exact imported metadata';copy[property]='copy';if(source[property]!=='A\ud800Z')throw 'source unchanged';}
"#);}
#[test]fn param_detached_copy_borrowed_deep_uses_boolean_without_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var x=document.getElementById('param'),calls=0,method=Node.prototype.cloneNode,copy=method.call(x,{valueOf:function(){calls++;throw 'conversion';},toString:function(){calls++;throw 'conversion';}});if(calls||copy===x||copy.parentNode!==null||copy.ownerDocument!==document||copy.firstChild!==null||copy.name!=='seed'||copy.value!=='seed'||copy.type!=='seed'||copy.valueType!=='seed'||copy.getAttributeNode('value')===x.getAttributeNode('value'))throw 'borrowed detached Param metadata';
"#);}

#[test]
fn param_detached_copy_deep_inert_import_and_native_clone_keep_independent_topology(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','param');source.value='deep';source.appendChild(owner.createTextNode('text'));source.appendChild(owner.createComment('marker'));var imported=document.importNode(source,true),copy=imported.cloneNode(true);for(var node of [imported,copy]){if(node.parentNode!==null||node.ownerDocument!==document||node.value!=='deep'||node.childNodes.length!==2||node.firstChild.data!=='text'||node.lastChild.data!=='marker'||node.firstChild.parentNode!==node||node.firstChild.ownerDocument!==document)throw 'independent deep area topology';}if(copy.firstChild===imported.firstChild||copy.firstChild===source.firstChild||source.ownerDocument!==owner||source.firstChild.ownerDocument!==owner)throw 'real deep owner identity';copy.firstChild.data='copy';if(imported.firstChild.data!=='text'||source.firstChild.data!=='text')throw 'deep copy isolation';"#);}


#[test]
fn param_detached_copy_resource_refusals_publish_nothing_and_recover(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var source=new Document().createElementNS('http://www.w3.org/1999/xhtml','param');source.value='retained';source.valueType='legacy';"}else{"var source=document.getElementById('param');source.value='retained';source.valueType='legacy';"});run(&mut d,&mut f,&mut p,"var attr=source.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let retained=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};let code=if inert{"var copy=document.importNode(source,true);"}else{"var copy=source.cloneNode(true);"};let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound")||e.contains("time"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=retained;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.value!=='retained'||source.getAttributeNode('value')!==attr||attr.ownerElement!==source||watch.takeRecords().length||document.getElementById('neighbor').value!=='seed')throw 'atomic copy refusal';");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"if(!(copy instanceof HTMLParamElement)||copy.parentNode!==null||copy.ownerDocument!==document||copy.value!=='retained'||copy.valueType!=='legacy'||copy.getAttributeNode('value')===attr||watch.takeRecords().length)throw 'fresh detached copy recovery';");assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());let(a,b,c)=p.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());}}
}


#[test]
fn param_detached_copy_saved_child_method_checks_origin_before_copy_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('param'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var method=frame.contentWindow.Node.prototype.cloneNode,copy=method.call(source,false);if(!(copy instanceof HTMLParamElement)||copy.parentNode!==null)throw 'same origin native copy';");p.set_location(&crate::navigation::address("https://other-copy.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute("method.call(source,false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);p.set_location(&crate::navigation::address("https://param-copy.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"copy=method.call(source,false);if(copy.valueType!=='seed'||copy.ownerDocument!==document||copy.parentNode!==null)throw 'fresh copy origin recovery';");}


#[test]
fn param_detached_copy_copies_nonce_unsafety_without_fabricating_source_mutation(){let(mut d,mut f,mut p)=fixture();let original=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("param")).unwrap();d.nonce_unsafe_nodes.insert(original);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes[original]);let Value::Host(copy)=p.runtime.execute("document.getElementById('param').cloneNode(false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("genuine copied node")};let copied=node_index(copy).unwrap();assert_ne!(copied,original);assert!(d.nonce_unsafe_nodes.contains(&copied));assert!(d.nonce_unsafe_nodes.contains(&original));assert_eq!(format!("{:?}",d.nodes[original]),before);assert!(p.state.detached_nodes.contains(&copied));assert!(!p.has_navigation_request());}


#[test]
fn param_detached_copy_active_handler_and_foreign_import_refuse_without_publication(){
 let(mut d,mut f,mut p)=fixture_with_markup("<html><body><param id=param name=seed value=seed type=seed valuetype=seed onclick='return 1;'><param id=clean name=seed value=seed type=seed valuetype=seed></body></html>");run(&mut d,&mut f,&mut p,"var source=document.getElementById('param');var watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());
 let e=p.runtime.execute("source.cloneNode(true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Cloning")||e.contains("handler"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);
 run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length)throw 'copy emitted record';if(source.getAttribute('onclick')!=='return 1;')throw 'parsed active metadata changed';var copy=document.getElementById('clean').cloneNode(true);if(copy.name!=='seed'||copy.parentNode!==null)throw 'fresh handler-free clone';var owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','param');inert.value='seed';inert.setAttributeNS('urn:foreign','foreign','kept');");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());
 let e=p.runtime.execute("document.importNode(inert,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("namespaced")||e.contains("unsupported"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);
 run(&mut d,&mut f,&mut p,"if(inert.value!=='seed'||inert.ownerDocument!==owner||inert.getAttributeNS('urn:foreign','foreign')!=='kept')throw 'foreign import preserved source';inert.removeAttributeNS('urn:foreign','foreign');var copy=document.importNode(inert,true);if(copy.value!=='seed'||copy.ownerDocument!==document||copy.parentNode!==null||inert.ownerDocument!==owner)throw 'fresh import recovery';");assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
}
